pub mod witnesses;

use vstd::prelude::*;
use dib_verus::{decode_with_steps, Decoded, Error, Mode};

pub mod ico;

verus! {

// Skeleton: proves the cross-crate DIB contract is usable from this crate; the
// real ICO implementation and its `decode_with_steps` call live in `crate::ico`.
pub fn skeleton(b: &[u8]) -> (r: Result<Decoded, Error>)
    ensures
        dib_verus::dib::decode_mp_eq(r, b@, Mode::IcoEntryDibSlack),
{
    let (r, _steps) = decode_with_steps(b, Mode::IcoEntryDibSlack);
    r
}

} // verus!
